{
  "contract": "SHIBB",
  "closure": {
    "site_function": "transferFrom",
    "site_call": ".call",
    "functions": [
      "transfer",
      "transferFrom",
      "_transfer"
    ],
    "justification": "These functions can be re-entered via the low-level call in transferFrom, affecting _ethReserves and _liquidityReserves."
  },
  "protocol": {
    "during_phase": "exposed",
    "allowed_callbacks": [
      "transfer",
      "transferFrom"
    ],
    "nesting_bound": {
      "transfer": 1,
      "transferFrom": 1
    }
  },
  "phases": {
    "function": "transferFrom",
    "pre": {
      "name": "pre",
      "from_marker": "start",
      "to_marker": "before_call"
    },
    "exposed": {
      "name": "exposed",
      "from_marker": "before_call",
      "to_marker": "after_call"
    },
    "post": {
      "name": "post",
      "from_marker": "after_call",
      "to_marker": "end"
    },
    "linearization_point": "after_call"
  },
  "ghost_state": [
    {
      "name": "inFlight",
      "sol_type": "uint256",
      "meaning": "Amount of ETH in-flight during the callback window",
      "backed_by_storage": false
    }
  ],
  "exposure_invariant": {
    "formula": "_ethReserves + _liquidityReserves == _balances[address(this)] + inFlight",
    "stable_formula": "_ethReserves + _liquidityReserves == _balances[address(this)]",
    "kind": "additive"
  },
  "composition": {
    "target_property": "_ethReserves + _liquidityReserves <= _balances[address(this)]",
    "rule": "The exposure invariant ensures that the sum of reserves is conserved across the callback window, allowing the target property to hold."
  }
}
